#include <iostream>
#include <memory>
#include <string>
#include <string_view>
#include <vector>
#include <functional>
#include <algorithm>

// ============================================================
// PATTERN 1: Factory Method
// ============================================================
struct Logger {
    virtual ~Logger() = default;
    virtual void log(std::string_view msg) const = 0;
    virtual std::string_view name() const = 0;
};

struct ConsoleLogger : Logger {
    void log(std::string_view msg) const override {
        std::cout << "[CONSOLE] " << msg << "\n";
    }
    std::string_view name() const override { return "ConsoleLogger"; }
};

struct PrefixLogger : Logger {
    explicit PrefixLogger(std::string prefix) : prefix_(std::move(prefix)) {}
    void log(std::string_view msg) const override {
        std::cout << prefix_ << " " << msg << "\n";
    }
    std::string_view name() const override { return prefix_; }
private:
    std::string prefix_;
};

// Factory — caller doesn't know the concrete type
std::unique_ptr<Logger> makeLogger(std::string_view type) {
    if (type == "console") return std::make_unique<ConsoleLogger>();
    if (type == "debug")   return std::make_unique<PrefixLogger>("[DEBUG]");
    if (type == "error")   return std::make_unique<PrefixLogger>("[ERROR]");
    throw std::invalid_argument("Unknown logger: " + std::string(type));
}

// ============================================================
// PATTERN 2: Strategy (via std::function)
// ============================================================
class Pipeline {
public:
    using Transform = std::function<std::string(std::string)>;

    void addStep(Transform t) { steps_.push_back(std::move(t)); }

    std::string run(std::string input) const {
        for (const auto& step : steps_)
            input = step(std::move(input));
        return input;
    }
private:
    std::vector<Transform> steps_;
};

// ============================================================
// PATTERN 3: Observer
// ============================================================
class EventBus {
public:
    using Handler = std::function<void(std::string_view)>;

    void subscribe(std::string id, Handler h) {
        subscribers_.push_back({std::move(id), std::move(h)});
    }

    void publish(std::string_view event) const {
        std::cout << "  [bus] publishing: '" << event << "'\n";
        for (const auto& [id, handler] : subscribers_)
            handler(event);
    }
private:
    std::vector<std::pair<std::string, Handler>> subscribers_;
};

// ============================================================
// PATTERN 4: Builder (fluent interface)
// ============================================================
struct Report {
    std::string title, body;
    std::vector<std::string> tags;

    class Builder {
    public:
        Builder& title(std::string t)  { r_.title = std::move(t); return *this; }
        Builder& body(std::string b)   { r_.body  = std::move(b); return *this; }
        Builder& tag(std::string tag)  { r_.tags.push_back(std::move(tag)); return *this; }
        Report build() { return std::move(r_); }
    private:
        Report r_;
    };
};

int main() {
    std::cout << "=== Day 17: Design Patterns ===\n\n";

    // ── Factory Method ─────────────────────────────────────────────────────
    std::cout << "[Factory Method]\n";
    for (auto type : {"console", "debug", "error"}) {
        auto logger = makeLogger(type);
        logger->log("System started");
    }

    // ── Strategy (std::function pipeline) ─────────────────────────────────
    std::cout << "\n[Strategy — Transform Pipeline]\n";
    Pipeline p;
    p.addStep([](std::string s) {
        std::transform(s.begin(), s.end(), s.begin(), ::toupper); return s; });
    p.addStep([](std::string s) { return ">> " + s + " <<"; });
    std::cout << "  result: " << p.run("hello world") << "\n";

    // ── Observer ───────────────────────────────────────────────────────────
    std::cout << "\n[Observer — EventBus]\n";
    EventBus bus;
    bus.subscribe("logger",    [](auto e){ std::cout << "  Logger heard: " << e << "\n"; });
    bus.subscribe("analytics", [](auto e){ std::cout << "  Analytics: tracking '" << e << "'\n"; });
    bus.publish("user.login");
    bus.publish("page.view");

    // ── Builder ────────────────────────────────────────────────────────────
    std::cout << "\n[Builder — Fluent Interface]\n";
    auto report = Report::Builder{}
        .title("Monthly Summary")
        .body("All metrics nominal.")
        .tag("monthly")
        .tag("automated")
        .build();
    std::cout << "  Report: '" << report.title << "' tags: ";
    for (const auto& t : report.tags) std::cout << t << " ";
    std::cout << "\n";

    return 0;
}
